    private static void rightClick(Minecraft mc,int x,int y,int z){
        mc.thePlayer.inventory.currentItem=8;mc.thePlayer.setSneaking(false);
        mc.objectMouseOver=new net.minecraft.util.MovingObjectPosition(x,y,z,1,net.minecraft.util.Vec3.createVectorHelper(x+.5,y+.05,z+.5));
        try{java.lang.reflect.Method method=null;for(java.lang.reflect.Method m:Minecraft.class.getDeclaredMethods())if(m.getParameterTypes().length==0&&(m.getName().equals("func_147121_ag")||m.getName().equals("rightClickMouse"))){method=m;break;}if(method==null)throw new NoSuchMethodException("Native Minecraft right-click");method.setAccessible(true);method.invoke(mc);}catch(ReflectiveOperationException e){throw new RuntimeException(e);}
    }
    private void capture(Minecraft mc,String name){check(GL11.glGetError()==GL11.GL_NO_ERROR,"OpenGL error");net.minecraft.util.ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
    private void finish(Minecraft mc,boolean failed){done=true;report.add("Failed: "+(failed?1:0));try{Files.write(mc.mcDataDir.toPath().resolve("checks-client.txt"),report,StandardCharsets.UTF_8);}catch(Exception x){throw new RuntimeException(x);}mc.displayGuiScreen(new GuiMainMenu());if(mc.theWorld!=null){mc.theWorld.sendQuittingDisconnectingPacket();mc.loadWorld(null);}mc.shutdown();}
